const isAuthor = user?.login && (await gh.getMR(prNumber))?.author?.login === user.login;
if (!isAuthor) {
  logger.info(`User ${user?.login} is not authorized to dismiss — skipping`);
  return;
}

matched = findings.filter((f) => {
  if (!f.id || typeof f.id !== 'string') return false;
  const hasAnchor = Boolean(thread.filePath) || thread.lineNumber !== undefined;
  if (!hasAnchor) return false;
  if (thread.filePath && typeof f.file === 'string' && f.file !== thread.filePath) return false;
  if (thread.lineNumber !== undefined && typeof f.line === 'number' && f.line !== thread.lineNumber) return false;
  return true;
});

} else {
  logger.info(`No findings matched dismissed comment ${parentCommentId} — nothing recorded, skipping minimize/ack`);
  return;
}

for (const fb of this.data.feedback) {
  if (
    (fb.signal_type === 'dismissed' && fb.signal_value === 'false_positive') ||
    fb.signal_type === 'disputed_comment'
  ) {
    disputedFindingIds.add(fb.finding_id);
  }
}
